CREATE TABLE public.erp_companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, country text NOT NULL DEFAULT 'Kenya', base_currency text NOT NULL DEFAULT 'KES', warehouse_id uuid UNIQUE REFERENCES public.stone_warehouses(id), kra_pin text, address text, phone text, email text, bank_details text, mpesa_details text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.erp_companies TO authenticated; GRANT ALL ON public.erp_companies TO service_role;
ALTER TABLE public.erp_companies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.erp_memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), user_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('owner','accountant','sales','warehouse','manager','viewer')), UNIQUE(company_id,user_id));
GRANT SELECT ON public.erp_memberships TO authenticated; GRANT ALL ON public.erp_memberships TO service_role;
ALTER TABLE public.erp_memberships ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.erp_access(p_company uuid, p_write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.erp_memberships WHERE company_id=p_company AND user_id=auth.uid() AND (NOT p_write OR role IN ('owner','accountant','manager'))) $$;
CREATE POLICY erp_company_read ON public.erp_companies FOR SELECT TO authenticated USING(public.erp_access(id));
CREATE POLICY erp_membership_read ON public.erp_memberships FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.erp_companies(name,warehouse_id) SELECT coalesce(company_name,name),id FROM public.stone_warehouses WHERE code='WH-NBO' AND country='Kenya';
INSERT INTO public.erp_memberships(company_id,user_id,role) SELECT c.id,r.user_id,'owner' FROM public.erp_companies c CROSS JOIN public.user_roles r WHERE r.role='admin';
CREATE TABLE public.erp_parties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), kind text NOT NULL CHECK(kind IN ('customer','supplier')), name text NOT NULL, company_name text, kra_pin text, vat_registered boolean NOT NULL DEFAULT false, phone text, whatsapp text, email text, address text, city text, county text, contact_person text, credit_limit numeric(18,2) NOT NULL DEFAULT 0 CHECK(credit_limit>=0), payment_terms integer NOT NULL DEFAULT 30 CHECK(payment_terms>=0), currency text NOT NULL DEFAULT 'KES', customer_type text, bank_details text, notes text, archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,company_id));
GRANT SELECT,INSERT,UPDATE ON public.erp_parties TO authenticated; GRANT ALL ON public.erp_parties TO service_role;
ALTER TABLE public.erp_parties ENABLE ROW LEVEL SECURITY;
CREATE POLICY erp_party_read ON public.erp_parties FOR SELECT TO authenticated USING(public.erp_access(company_id));
CREATE POLICY erp_party_create ON public.erp_parties FOR INSERT TO authenticated WITH CHECK(public.erp_access(company_id,true) OR EXISTS(SELECT 1 FROM public.erp_memberships WHERE company_id=erp_parties.company_id AND user_id=auth.uid() AND role='sales'));
CREATE POLICY erp_party_edit ON public.erp_parties FOR UPDATE TO authenticated USING(public.erp_access(company_id,true)) WITH CHECK(public.erp_access(company_id,true));
CREATE TABLE public.erp_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), code text NOT NULL, name text NOT NULL, category text NOT NULL CHECK(category IN ('asset','liability','equity','revenue','cost','expense')), UNIQUE(company_id,code), UNIQUE(id,company_id));
GRANT SELECT ON public.erp_accounts TO authenticated; GRANT ALL ON public.erp_accounts TO service_role;
ALTER TABLE public.erp_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY erp_account_read ON public.erp_accounts FOR SELECT TO authenticated USING(public.erp_access(company_id));
CREATE TABLE public.erp_tax_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), name text NOT NULL, rate numeric(7,4) NOT NULL CHECK(rate>=0 AND rate<=100), treatment text NOT NULL CHECK(treatment IN ('standard','zero','exempt','non_vat','custom')), UNIQUE(company_id,name), UNIQUE(id,company_id));
GRANT SELECT ON public.erp_tax_codes TO authenticated; GRANT ALL ON public.erp_tax_codes TO service_role;
ALTER TABLE public.erp_tax_codes ENABLE ROW LEVEL SECURITY;
CREATE POLICY erp_tax_read ON public.erp_tax_codes FOR SELECT TO authenticated USING(public.erp_access(company_id));
CREATE TABLE public.erp_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), kind text NOT NULL CHECK(kind IN ('invoice','bill','expense','sales_order','purchase_order','credit_note')), number text NOT NULL, supplier_reference text, party_id uuid, document_date date NOT NULL DEFAULT current_date, due_date date NOT NULL DEFAULT current_date+30, currency text NOT NULL DEFAULT 'KES' CHECK(currency ~ '^[A-Z]{3}$'), exchange_rate numeric(18,8) NOT NULL DEFAULT 1 CHECK(exchange_rate>0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted','cancelled')), subtotal numeric(18,2) NOT NULL DEFAULT 0, tax_amount numeric(18,2) NOT NULL DEFAULT 0, total numeric(18,2) NOT NULL DEFAULT 0, notes text, posted_at timestamptz, created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,number), UNIQUE(id,company_id), FOREIGN KEY(party_id,company_id) REFERENCES public.erp_parties(id,company_id));
CREATE UNIQUE INDEX erp_supplier_reference_unique ON public.erp_documents(company_id,party_id,supplier_reference) WHERE kind='bill' AND supplier_reference IS NOT NULL;
GRANT SELECT ON public.erp_documents TO authenticated; GRANT ALL ON public.erp_documents TO service_role;
ALTER TABLE public.erp_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY erp_doc_read ON public.erp_documents FOR SELECT TO authenticated USING(public.erp_access(company_id));
CREATE TABLE public.erp_document_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), document_id uuid NOT NULL, description text NOT NULL, quantity numeric(18,4) NOT NULL CHECK(quantity>0), unit text NOT NULL DEFAULT 'Sqm', unit_price numeric(18,2) NOT NULL CHECK(unit_price>=0), discount numeric(18,2) NOT NULL DEFAULT 0 CHECK(discount>=0), tax_code_id uuid NOT NULL, net_amount numeric(18,2) NOT NULL, tax_amount numeric(18,2) NOT NULL, FOREIGN KEY(document_id,company_id) REFERENCES public.erp_documents(id,company_id), FOREIGN KEY(tax_code_id,company_id) REFERENCES public.erp_tax_codes(id,company_id));
GRANT SELECT ON public.erp_document_items TO authenticated; GRANT ALL ON public.erp_document_items TO service_role;
ALTER TABLE public.erp_document_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY erp_item_read ON public.erp_document_items FOR SELECT TO authenticated USING(public.erp_access(company_id));
CREATE TABLE public.erp_journals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), source_document_id uuid, source_payment_id uuid, description text NOT NULL, journal_date date NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,company_id), UNIQUE(source_document_id), UNIQUE(source_payment_id), FOREIGN KEY(source_document_id,company_id) REFERENCES public.erp_documents(id,company_id));
GRANT SELECT ON public.erp_journals TO authenticated; GRANT ALL ON public.erp_journals TO service_role;
ALTER TABLE public.erp_journals ENABLE ROW LEVEL SECURITY;
CREATE POLICY erp_journal_read ON public.erp_journals FOR SELECT TO authenticated USING(public.erp_access(company_id));
CREATE TABLE public.erp_journal_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), journal_id uuid NOT NULL, account_id uuid NOT NULL, debit numeric(18,2) NOT NULL DEFAULT 0 CHECK(debit>=0), credit numeric(18,2) NOT NULL DEFAULT 0 CHECK(credit>=0), CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)), FOREIGN KEY(journal_id,company_id) REFERENCES public.erp_journals(id,company_id), FOREIGN KEY(account_id,company_id) REFERENCES public.erp_accounts(id,company_id));
GRANT SELECT ON public.erp_journal_lines TO authenticated; GRANT ALL ON public.erp_journal_lines TO service_role;
ALTER TABLE public.erp_journal_lines ENABLE ROW LEVEL SECURITY;
CREATE POLICY erp_line_read ON public.erp_journal_lines FOR SELECT TO authenticated USING(public.erp_access(company_id));
CREATE TABLE public.erp_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), document_id uuid NOT NULL, account_id uuid NOT NULL, amount numeric(18,2) NOT NULL CHECK(amount>0), payment_date date NOT NULL DEFAULT current_date, reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,company_id), UNIQUE(company_id,reference), FOREIGN KEY(document_id,company_id) REFERENCES public.erp_documents(id,company_id), FOREIGN KEY(account_id,company_id) REFERENCES public.erp_accounts(id,company_id));
GRANT SELECT ON public.erp_payments TO authenticated; GRANT ALL ON public.erp_payments TO service_role;
ALTER TABLE public.erp_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY erp_payment_read ON public.erp_payments FOR SELECT TO authenticated USING(public.erp_access(company_id));
ALTER TABLE public.erp_journals ADD CONSTRAINT erp_source_payment_fk FOREIGN KEY(source_payment_id,company_id) REFERENCES public.erp_payments(id,company_id);
CREATE TABLE public.erp_audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.erp_companies(id), user_id uuid NOT NULL DEFAULT auth.uid(), action text NOT NULL, record_id uuid, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.erp_audit_events TO authenticated; GRANT ALL ON public.erp_audit_events TO service_role;
ALTER TABLE public.erp_audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY erp_audit_read ON public.erp_audit_events FOR SELECT TO authenticated USING(public.erp_access(company_id));
CREATE FUNCTION public.erp_check_balanced() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE j uuid; n integer; d numeric; c numeric; BEGIN j=NEW.journal_id; SELECT count(*),coalesce(sum(debit),0),coalesce(sum(credit),0) INTO n,d,c FROM public.erp_journal_lines WHERE journal_id=j; IF n<2 OR d<>c THEN RAISE EXCEPTION 'Journal must have at least two lines and balance'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER erp_balanced_journal AFTER INSERT ON public.erp_journal_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.erp_check_balanced();
CREATE FUNCTION public.erp_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Posted accounting records are immutable'; END $$;
CREATE TRIGGER erp_journal_immutable BEFORE UPDATE OR DELETE ON public.erp_journals FOR EACH ROW EXECUTE FUNCTION public.erp_immutable();
CREATE TRIGGER erp_lines_immutable BEFORE UPDATE OR DELETE ON public.erp_journal_lines FOR EACH ROW EXECUTE FUNCTION public.erp_immutable();
CREATE TRIGGER erp_payments_immutable BEFORE UPDATE OR DELETE ON public.erp_payments FOR EACH ROW EXECUTE FUNCTION public.erp_immutable();
CREATE TRIGGER erp_audit_immutable BEFORE UPDATE OR DELETE ON public.erp_audit_events FOR EACH ROW EXECUTE FUNCTION public.erp_immutable();
CREATE FUNCTION public.erp_document_lock() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status='posted' THEN RAISE EXCEPTION 'Issued documents cannot be edited or deleted'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER erp_document_immutable BEFORE UPDATE OR DELETE ON public.erp_documents FOR EACH ROW EXECUTE FUNCTION public.erp_document_lock();
CREATE FUNCTION public.erp_initialize(p_company uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.erp_access(p_company,true) THEN RAISE EXCEPTION 'Company accounting access required'; END IF; INSERT INTO public.erp_accounts(company_id,code,name,category) VALUES(p_company,'1000','Cash','asset'),(p_company,'1010','Bank','asset'),(p_company,'1020','M-Pesa','asset'),(p_company,'1100','Accounts Receivable','asset'),(p_company,'1200','Inventory','asset'),(p_company,'1300','Input VAT','asset'),(p_company,'2000','Accounts Payable','liability'),(p_company,'2100','Output VAT','liability'),(p_company,'3000','Owner Capital','equity'),(p_company,'3100','Retained Earnings','equity'),(p_company,'4000','Stone Sales','revenue'),(p_company,'5000','Stone Cost of Goods Sold','cost'),(p_company,'6000','Operating Expenses','expense') ON CONFLICT(company_id,code) DO NOTHING; INSERT INTO public.erp_tax_codes(company_id,name,rate,treatment) VALUES(p_company,'VAT 16%',16,'standard'),(p_company,'Zero-rated',0,'zero'),(p_company,'Exempt',0,'exempt'),(p_company,'Non-VAT',0,'non_vat') ON CONFLICT(company_id,name) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.erp_initialize(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.erp_initialize(uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.erp_access(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.erp_access(uuid,boolean) TO authenticated;